import sys

def articulationPoints(V, adj):
    def dfs(at, parent, discovery_times, low_links, visited, articulation_points, time):
        visited[at] = True
        discovery_times[at] = low_links[at] = time
        children = 0
        for to in adj[at]:
            if to == parent:
                continue
            if not visited[to]:
                children += 1
                dfs(to, at, discovery_times, low_links, visited, articulation_points, time + 1)
                low_links[at] = min(low_links[at], low_links[to])
                if parent != -1 and low_links[to] >= discovery_times[at]:
                    articulation_points.add(at)
            else:
                low_links[at] = min(low_links[at], discovery_times[to])
        if parent == -1 and children > 1:
            articulation_points.add(at)

    discovery_times = [0] * V
    low_links = [0] * V
    visited = [False] * V
    articulation_points = set()

    for i in range(V):
        if not visited[i]:
            dfs(i, -1, discovery_times, low_links, visited, articulation_points, 0)

    return sorted(articulation_points) if articulation_points else [-1]

if __name__ == "__main__":
    import sys
    input = sys.stdin.read().splitlines()
    V = int(input[0])
    adj = [[] for _ in range(V)]
    index = 1
    for i in range(V):
        neighbors = list(map(int, input[index].split()))
        adj[i] = neighbors
        index += 1
    result = articulationPoints(V, adj)
    print(" ".join(map(str, result)))
